        }
      ],
      "dependent_passages": [
        {
          "reason": "При проверке возможного сокращения первого итога нужно сохранить связный переход к заключительному образу и не повторить тот же вывод.",
          "anchors": [
            {
              "utterance_index": 21,
              "quote": "Но к решению привели расспросы: кто приносил воду, откуда, кто её пил."
            }
          ]
        }
      ]
    }
  }
}
